func (q *Queries) NextCategoryOrder(ctx context.Context, outletID string) (int32, error) {
	row := q.db.QueryRow(ctx, nextCategoryOrder, outletID)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}

