const setCategoryOrder = `-- name: SetCategoryOrder :exec
UPDATE menu_categories c SET sort_order = o.pos - 1, updated_at = now()
FROM unnest($2::text[]) WITH ORDINALITY AS o(category_id, pos)
WHERE c.category_id = o.category_id AND c.outlet_id = $1 AND c.sort_order <> o.pos - 1
`

